/* Independent example checker for the declared subset. Not FRET/LTLSIM model checking.
 * Expected outcomes are specified by each boundary example. No eval of external input.
 * Predicates come only from the locally authored catalog generated by build.cjs.
 */
const fs=require('fs'),path=require('path'),assert=require('assert');
const read=n=>JSON.parse(fs.readFileSync(path.join(__dirname,n),'utf8'));
const projects=read('catalog.json'), all=projects.flatMap(p=>p.requirements);
const get=id=>all.find(r=>r.reqid===id);
function expression(expr,sample){const keys=Object.keys(sample);return Function(...keys,'return ('+expr+');')(...keys.map(k=>sample[k]));}
function snapshot(id,sample){const r=get(id);assert(r.check.timing==='immediately');if(!expression(r.check.trigger,sample))return 'NOT_TRIGGERED';return expression(r.check.predicate,sample)?'SATISFIED':'VIOLATED';}
function temporal(id,trace){
 const r=get(id),c=r.check;let triggered=false,pending=false;
 for(let t=0;t<trace.length;t++){
  const active=expression(c.trigger,trace[t]);
  const edge=c.timing!=='within3-level';
  if(!active||(edge&&t>0&&expression(c.trigger,trace[t-1])))continue;
  triggered=true;const end=c.timing==='eventually'?trace.length-1:Math.min(t+3,trace.length-1);
  let found=false;for(let u=t;u<=end;u++) if(expression(c.predicate,trace[u]))found=true;
  if(!found){if(c.timing==='eventually'||t+3>=trace.length)pending=true;else return 'VIOLATED';}
 }
 return !triggered?'NOT_TRIGGERED':pending?'INCOMPLETE':'SATISFIED';
}
const results=[];
function check(id,label,sample,expected,trace=false){const actual=trace?temporal(id,sample):snapshot(id,sample);results.push({id,label,expected,actual,ok:actual===expected,sample});}
const door={scope_approved:true,minimum_age:6,maximum_age:12,test_active:true,p0_active:true,fixture_approved:true,force_n:10,hands_used:1,inspection_active:true,sharp_edges_present:false};
for(const [id,patch] of [['DOOR-01',{minimum_age:8}],['DOOR-02',{fixture_approved:false}],['DOOR-03',{force_n:10.001}],['DOOR-04',{hands_used:2}],['DOOR-08',{sharp_edges_present:true}]]){
 check(id,'satisfying boundary',door,'SATISFIED');check(id,'single violated constraint',{...door,...patch},'VIOLATED');
}
check('DOOR-03','Inactive trial cannot establish satisfaction',{...door,test_active:false,force_n:100},'NOT_TRIGGERED');
for(const [id,trig,resp] of [['DOOR-05','open_requested','latch_released'],['DOOR-06','open_requested','opened_90'],['DOOR-07','close_requested','closed_and_latched']]){
 check(id,'event followed by observed response',[{[trig]:true,[resp]:false},{[trig]:false,[resp]:true}],'SATISFIED',true);
 check(id,'no deadline: unfinished observation',[{[trig]:true,[resp]:false},{[trig]:false,[resp]:false}],'INCOMPLETE',true);
}
const truss={assessment_active:true,load_kgf:1000,offset_m:2,steel_only:true,solid_circular:true,fixed_section:true,allowed_lengths:true,available_grid_only:true,connected_to_wall:true,stable:true,joints_rigid_enough:true,displacement_m:0.019,vertical_displacement_m:0.019,yield_utilization:1,buckling_utilization:1,selection_complete:true,feasible:true,enumeration_complete:true,mass_kg:12,enumerated_min_mass_kg:12};
for(const [id,patch] of [['01',{load_kgf:999}],['02',{solid_circular:false}],['03',{allowed_lengths:false}],['04',{stable:false}],['05',{displacement_m:0.02}],['06',{yield_utilization:1.001}],['07',{buckling_utilization:1.001}],['08',{mass_kg:13}]]){
 check('TRUSS-'+id,'satisfying synthetic solver snapshot',truss,'SATISFIED');check('TRUSS-'+id,'violated synthetic solver snapshot',{...truss,...patch},'VIOLATED');
}
check('TRUSS-08','No exhaustive search certificate',{...truss,enumeration_complete:false},'VIOLATED');
const different={...truss,displacement_m:Math.hypot(0.015,0.015),vertical_displacement_m:0.015};
check('TRUSS-05','15 mm horizontal + 15 mm vertical',different,'VIOLATED');
check('TRUSS-V-05','Same displacement, vertical-only meaning',different,'SATISFIED');
check('TRUSS-V-05','Strict 20 mm boundary',{...truss,vertical_displacement_m:0.02},'VIOLATED');
for(const id of ['RESP-EDGE','RESP-LEVEL']){
 check(id,'Response at inclusive deadline',[0,1,2,3].map(t=>({request:t===0,response:t===3})),'SATISFIED',true);
 check(id,'Missing response at complete deadline',[0,1,2,3].map(t=>({request:t===0,response:false})),'VIOLATED',true);
 check(id,'Truncated trace', [{request:true,response:false},{request:false,response:false}],'INCOMPLETE',true);
 check(id,'No request', [{request:false,response:false}],'NOT_TRIGGERED',true);
}
const held=[0,1,2,3,4,5,6,7].map(t=>({request:t<=4,response:t===1}));
check('RESP-EDGE','Held request; one early response',held,'SATISFIED',true);
check('RESP-LEVEL','Same trace; repeated obligations',held,'VIOLATED',true);
const http=read('http-observations.json');
for(const row of http){const sample={head_complete:true,head_bytes:row.head_bytes,length_present:row.head_length!=='absent',head_length:row.head_length==='absent'?0:Number(row.head_length),get_bytes:row.get_bytes};
 check('HTTP-01',`${row.mode} ${row.path} — raw socket observation`,sample,row.C1?'SATISFIED':'VIOLATED');
 check('HTTP-02',`${row.mode} ${row.path} — optional header`,sample,!sample.length_present?'NOT_TRIGGERED':row.C2?'SATISFIED':'VIOLATED');
}
for(const row of read('workflow-observations.json')){
 const id=`M${row.method}-L${row.level}`;
 check(id,'Existing executable ledger schedule',row,'SATISFIED');
 check(id,'Mutation: wrong candidate count',{...row,candidate_count:row.candidate_count+1},'VIOLATED');
 if(row.level===6){check(`M${row.method}-FINAL`,'Existing selected package',row,'SATISFIED');check(`M${row.method}-FINAL`,'Wrong selected package',{...row,selected_package:10},'VIOLATED');}
}
for(let m=1;m<=5;m++){
 const s={accepted:true,current_evidence_count:4,evidence_valid:true,test_failed:false};
 check(`M${m}-ACCEPT`,'All four current criteria passed',s,'SATISFIED');
 check(`M${m}-ACCEPT`,'Zero entropy is insufficient: evidence missing',{...s,current_evidence_count:0},'VIOLATED');
 check(`M${m}-ACCEPT`,'Stale or invalid evidence',{...s,evidence_valid:false},'VIOLATED');
 check(`M${m}-ACCEPT`,'Failed current test',{...s,test_failed:true},'VIOLATED');
}
const covered=new Set(results.map(r=>r.id));assert.strictEqual(covered.size,all.length,'Every formalized requirement needs a behavioral example');
const summary={checker:'Independent authored subset checker; NOT a FRET simulator or model checker',cases:results.length,passed:results.filter(r=>r.ok).length,failed:results.filter(r=>!r.ok).length,requirements_covered:covered.size,http_requests:40,workflow_snapshots:30,note:'INCOMPLETE is a conservative evidence label. FRET weak finite-trace semantics may allow truncated obligations; see its exact formulas.'};
fs.writeFileSync(path.join(__dirname,'example-results.json'),JSON.stringify({summary,results},null,2));
console.log(JSON.stringify(summary,null,2));assert.strictEqual(summary.failed,0,'Unexpected boundary result');
